/**
 * Postgres system of record — Drizzle schema (ADR-0011).
 *
 * Postgres on Neon, reached from Workers via Hyperdrive. This is the system of
 * record, the double-entry ledger included; money NEVER lives in D1.
 *
 * Modeling rules (doctrine — ADR-0007/0008/0010/0011, packages/proto):
 * - All money is bigint integer kobo (1/100 naira). No floats; negative amounts
 *   are forbidden by the settlement function and by CHECK constraints here.
 * - All wall-clock columns are timestamptz. All ids are text, issued by the
 *   edge (Durable Objects / archive consumer), never generated by the DB.
 * - Settlement is the ONLY money movement (ADR-0007); aborts never refund
 *   fully (ADR-0008); the platform absorbs capped, ambiguous losses (ADR-0007).
 * - Vendor names never appear here (ADR-0009): payments/KYC speak in captures,
 *   holds, releases, and verifications — provider API shapes stay in the
 *   integration layer.
 *
 * Participant ids (Buyer/Seller/Runner) are issued by the edge identity layer
 * and stored as text references. ADR-0010 deliberately lists no participants
 * table; whether to anchor them in Postgres is a founder decision (see README).
 */

import {
  bigint,
  boolean,
  check,
  index,
  integer,
  jsonb,
  pgTable,
  text,
  time,
  timestamp,
  uniqueIndex,
} from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";

/* ------------------------------------------------------------------------ */
/* Snapshots mirroring packages/domain and packages/proto shapes.            */
/* Keep in sync with packages/domain/src/settlement.ts and                   */
/* packages/proto/src/{settlement,payments,run}.ts — these are stored        */
/* verbatim as the durable record of what was computed and why.              */
/* ------------------------------------------------------------------------ */

export interface SellerAmountSnapshot {
  sellerId: string;
  amountKobo: number;
  stopCompleted: boolean;
}

export interface AbortSplitSnapshot {
  /** Fraction of delivery price paid to the Runner for disruption, basis points. */
  disruptionCompensationBps: number;
  /** Fraction of delivery price retained by the platform, basis points. */
  platformFeeBps: number;
  /** Maximum loss absorbed by the platform in an ambiguous dispute, kobo. */
  ambiguousLossCapKobo: number;
}

/** Mirror of SettlementInput in @market-runs/domain. */
export interface SettlementInputSnapshot {
  mode: "completed" | "aborted" | "disputed";
  sellers: SellerAmountSnapshot[];
  deliveryPriceKobo: number;
  deliveryMarginKobo: number;
  goodsCommissionBps: number;
  abortSplit?: AbortSplitSnapshot;
  dispute?: { ambiguous: boolean; requestedPlatformLossKobo?: number };
}

/** Mirror of SettlementOutcome in @market-runs/domain. */
export interface SettlementOutcomeSnapshot {
  sellers: Array<{ sellerId: string; amountKobo: number }>;
  runnerKobo: number;
  platformKobo: number;
  buyerRefundKobo: number;
  platformLossKobo: number;
}

/** Mirror of Delivery in packages/proto/src/primitives.ts. */
export type DeliverySnapshot =
  | { kind: "plus-code"; plusCode: string }
  | { kind: "muster-point"; name: string };

/** Mirror of RunStatus in packages/proto/src/run.ts. */
export const RUN_STATUSES = ["assigned", "collecting", "delivering", "delivered", "closed", "aborted"] as const;

/** Mirror of Role in packages/proto/src/primitives.ts. */
export const PARTICIPANT_ROLES = ["Buyer", "Seller", "Runner"] as const;

/** Mirror of KycVerificationStatus in packages/proto/src/payments.ts. */
export const KYC_STATUSES = ["pending", "verified", "failed"] as const;

/** Settlement modes — mirror of SettlementMode in packages/domain/src/settlement.ts. */
export const SETTLEMENT_MODES = ["completed", "aborted", "disputed"] as const;

/**
 * Why a Product left the system (GLOSSARY.md: products are retired, never
 * resurrected): accepted into a Cart (sold), died with its Intent (expired),
 * withdrawn by the Seller, or retired atomically with its Cart (cart_expired).
 */
export const RETIREMENT_REASONS = ["accepted", "expired", "withdrawn", "cart_expired"] as const;

/**
 * Chart of accounts for the double-entry ledger. Every kobo movement in the
 * system is recorded as balanced debit/credit legs under one of these
 * accounts, always tied to a settlement_record (ADR-0007 — money moves only
 * through settlement). `party_id` on a leg carries the participant the leg
 * concerns (Seller payout, Runner payout, Buyer refund); platform accounts
 * leave it NULL. The account set itself is a founder sign-off item (README).
 */
export const LEDGER_ACCOUNTS = [
  "buyer_capture",
  "seller_payable",
  "runner_payable",
  "platform_revenue",
  "buyer_refund",
  "platform_loss",
] as const;
export type LedgerAccount = (typeof LEDGER_ACCOUNTS)[number];

/* ------------------------------------------------------------------------ */
/* Markets, stores, shop items                                              */
/* ------------------------------------------------------------------------ */

export const markets = pgTable(
  "markets",
  {
    id: text("id").primaryKey(),
    /** Named geographic zone locals already recognize (GLOSSARY.md); unique. */
    name: text("name").notNull().unique(),
    /** Daily local opening/closing clock times; the close gate is enforced by MarketDO. */
    opensAt: time("opens_at").notNull(),
    closesAt: time("closes_at").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    check("markets_opens_before_closes", sql`${table.opensAt} < ${table.closesAt}`),
  ],
);

export const stores = pgTable(
  "stores",
  {
    id: text("id").primaryKey(),
    /** Seller (participant id) operating this storefront. */
    sellerId: text("seller_id").notNull(),
    /** The market this store is registered to; fixes which market it trades in. */
    marketId: text("market_id")
      .notNull()
      .references(() => markets.id),
    name: text("name").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("stores_market_id_idx").on(table.marketId),
    index("stores_seller_id_idx").on(table.sellerId),
  ],
);

export const shopItems = pgTable(
  "shop_items",
  {
    id: text("id").primaryKey(),
    storeId: text("store_id")
      .notNull()
      .references(() => stores.id),
    name: text("name").notNull(),
    /** Structured catalog attributes used to match intents (per-market vocab, ADR-0006). */
    attributes: jsonb("attributes").notNull().default(sql`'{}'::jsonb`),
    active: boolean("active").notNull().default(true),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("shop_items_store_id_idx").on(table.storeId),
  ],
);

/* ------------------------------------------------------------------------ */
/* KYC records (ADR-0004 universal KYC; ADR-0009 vendor-neutral)            */
/* ------------------------------------------------------------------------ */

export const kycRecords = pgTable(
  "kyc_records",
  {
    id: text("id").primaryKey(),
    participantId: text("participant_id").notNull(),
    role: text("role").notNull(),
    status: text("status").notNull(),
    /** Integration-layer verification reference (vendor-neutral, ADR-0009). */
    verificationId: text("verification_id"),
    verifiedAt: timestamp("verified_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    uniqueIndex("kyc_records_participant_role_unique").on(table.participantId, table.role),
    index("kyc_records_participant_id_idx").on(table.participantId),
    index("kyc_records_status_idx").on(table.status),
    check("kyc_records_role_valid", sql`${table.role} IN ('Buyer', 'Seller', 'Runner')`),
    check("kyc_records_status_valid", sql`${table.status} IN ('pending', 'verified', 'failed')`),
  ],
);

/* ------------------------------------------------------------------------ */
/* Product retirement snapshots (ADR-0010: retirement → archive queue →     */
/* Postgres/R2, then DO storage is deleted). Products are retired, never      */
/* resurrected (GLOSSARY.md).                                                 */
/* ------------------------------------------------------------------------ */

export const archivedProducts = pgTable(
  "archived_products",
  {
    /** The ephemeral product's own id. */
    id: text("id").primaryKey(),
    intentId: text("intent_id").notNull(),
    /** Set once the product was accepted into a cart; NULL otherwise. */
    cartId: text("cart_id"),
    storeId: text("store_id")
      .notNull()
      .references(() => stores.id),
    /** Inherited from the store, frozen at retirement for market analytics. */
    marketId: text("market_id")
      .notNull()
      .references(() => markets.id),
    buyerId: text("buyer_id").notNull(),
    finalPriceKobo: bigint("final_price_kobo", { mode: "number" }).notNull(),
    quantity: integer("quantity").notNull(),
    /** Why retired: accepted | expired | withdrawn | cart_expired. */
    retirementReason: text("retirement_reason").notNull(),
    /** The ProductDO's full final state at retirement, verbatim. */
    finalState: jsonb("final_state").notNull(),
    retiredAt: timestamp("retired_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("archived_products_store_id_idx").on(table.storeId),
    index("archived_products_market_id_idx").on(table.marketId),
    index("archived_products_retired_at_idx").on(table.retiredAt),
    check("archived_products_final_price_nonnegative", sql`${table.finalPriceKobo} >= 0`),
    check("archived_products_quantity_positive", sql`${table.quantity} > 0`),
    check(
      "archived_products_retirement_reason_valid",
      sql`${table.retirementReason} IN ('accepted', 'expired', 'withdrawn', 'cart_expired')`,
    ),
  ],
);

/* ------------------------------------------------------------------------ */
/* Run close records (GLOSSARY.md: one Run per Cart, one Runner per Run).   */
/* ------------------------------------------------------------------------ */

export const runsArchive = pgTable(
  "runs_archive",
  {
    id: text("id").primaryKey(),
    cartId: text("cart_id").notNull(),
    marketId: text("market_id")
      .notNull()
      .references(() => markets.id),
    buyerId: text("buyer_id").notNull(),
    runnerId: text("runner_id").notNull(),
    status: text("status").notNull(),
    /** Where the run ends: buyer plus-code or partner-operated muster point. */
    delivery: jsonb("delivery").$type<DeliverySnapshot>().notNull(),
    /** Floor-rate delivery price for this run, integer kobo (ADR-0013: MVP is floor-rate only). */
    floorRateKobo: bigint("floor_rate_kobo", { mode: "number" }).notNull(),
    startedAt: timestamp("started_at", { withTimezone: true }),
    finalDeliveryAt: timestamp("final_delivery_at", { withTimezone: true }),
    closedAt: timestamp("closed_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("runs_archive_market_id_idx").on(table.marketId),
    index("runs_archive_buyer_id_idx").on(table.buyerId),
    index("runs_archive_runner_id_idx").on(table.runnerId),
    index("runs_archive_status_idx").on(table.status),
    index("runs_archive_closed_at_idx").on(table.closedAt),
    check("runs_archive_status_valid", sql`${table.status} IN ('assigned', 'collecting', 'delivering', 'delivered', 'closed', 'aborted')`),
    check("runs_archive_floor_rate_nonnegative", sql`${table.floorRateKobo} >= 0`),
  ],
);

/* ------------------------------------------------------------------------ */
/* Settlement records — the computation at Run close (GLOSSARY.md). Full    */
/* inputs and full outcome are stored verbatim; the discrete kobo columns    */
/* exist for reconciliation and ops-console queries (ADR-0011).              */
/* ------------------------------------------------------------------------ */

export const settlementRecords = pgTable(
  "settlement_records",
  {
    id: text("id").primaryKey(),
    runId: text("run_id")
      .notNull()
      .references(() => runsArchive.id),
    mode: text("mode").notNull(),
    goodsTotalKobo: bigint("goods_total_kobo", { mode: "number" }).notNull(),
    runnerKobo: bigint("runner_kobo", { mode: "number" }).notNull(),
    platformKobo: bigint("platform_kobo", { mode: "number" }).notNull(),
    buyerRefundKobo: bigint("buyer_refund_kobo", { mode: "number" }).notNull(),
    platformLossKobo: bigint("platform_loss_kobo", { mode: "number" }).notNull(),
    /** Full SettlementInput as computed by the RunDO, verbatim. */
    inputs: jsonb("inputs").$type<SettlementInputSnapshot>().notNull(),
    /** Full SettlementOutcome as returned by the settlement function, verbatim. */
    outcome: jsonb("outcome").$type<SettlementOutcomeSnapshot>().notNull(),
    /** When payment was released (post dispute window, GLOSSARY.md timers). */
    releasedAt: timestamp("released_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("settlement_records_run_id_idx").on(table.runId),
    index("settlement_records_mode_idx").on(table.mode),
    index("settlement_records_created_at_idx").on(table.createdAt),
    check("settlement_records_mode_valid", sql`${table.mode} IN ('completed', 'aborted', 'disputed')`),
    check(
      "settlement_records_amounts_nonnegative",
      sql`${table.goodsTotalKobo} >= 0 AND ${table.runnerKobo} >= 0 AND ${table.platformKobo} >= 0 AND ${table.buyerRefundKobo} >= 0 AND ${table.platformLossKobo} >= 0`,
    ),
  ],
);

/* ------------------------------------------------------------------------ */
/* Double-entry financial ledger (ADR-0011: the ledger lives in Postgres,   */
/* never D1). Every kobo movement is a pair (or set) of legs — one debit,    */
/* one credit — summing to zero per settlement_record. This table is the     */
/* financial ledger; ledger_entries.settlement_record_id is its tie to the   */
/* settlement that authorized the movement (ADR-0007: no side channels).     */
/* ------------------------------------------------------------------------ */

export const ledgerEntries = pgTable(
  "ledger_entries",
  {
    id: text("id").primaryKey(),
    settlementRecordId: text("settlement_record_id")
      .notNull()
      .references(() => settlementRecords.id),
    /** One of LEDGER_ACCOUNTS. */
    account: text("account").notNull(),
    /** Participant this leg concerns (seller/runner/buyer payables); NULL for platform accounts. */
    partyId: text("party_id"),
    debitKobo: bigint("debit_kobo", { mode: "number" }).notNull().default(0),
    creditKobo: bigint("credit_kobo", { mode: "number" }).notNull().default(0),
    memo: text("memo").notNull().default(""),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (table) => [
    index("ledger_entries_settlement_record_id_idx").on(table.settlementRecordId),
    index("ledger_entries_account_party_id_idx").on(table.account, table.partyId),
    index("ledger_entries_created_at_idx").on(table.createdAt),
    check(
      "ledger_entries_single_sided",
      sql`(${table.debitKobo} > 0) <> (${table.creditKobo} > 0)`,
    ),
    check(
      "ledger_entries_directions_nonnegative",
      sql`${table.debitKobo} >= 0 AND ${table.creditKobo} >= 0`,
    ),
  ],
);

/* ------------------------------------------------------------------------ */
/* Disputes (ADR-0007: evidence-first; ambiguous losses absorbed, capped).  */
/* ------------------------------------------------------------------------ */

export const disputes = pgTable(
  "disputes",
  {
    id: text("id").primaryKey(),
    runId: text("run_id")
      .notNull()
      .references(() => runsArchive.id),
    /** The settlement computed for this dispute, once released; NULL while open. */
    settlementRecordId: text("settlement_record_id").references(() => settlementRecords.id),
    raisedByParticipantId: text("raised_by_participant_id").notNull(),
    /** Signed R2 references to photo evidence / scan logs for this dispute. */
    evidenceRefs: text("evidence_refs").array().notNull().default(sql`'{}'::text[]`),
    /** TRUE when the evidence layer could not resolve the dispute unambiguously. */
    ambiguous: boolean("ambiguous").notNull().default(false),
    /** Loss the platform absorbed for this dispute, integer kobo (cap in the settlement input). */
    absorbedLossKobo: bigint("absorbed_loss_kobo", { mode: "number" }).notNull().default(0),
    status: text("status").notNull().default("open"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    resolvedAt: timestamp("resolved_at", { withTimezone: true }),
  },
  (table) => [
    index("disputes_run_id_idx").on(table.runId),
    index("disputes_status_idx").on(table.status),
    check("disputes_status_valid", sql`${table.status} IN ('open', 'under_review', 'resolved')`),
    check("disputes_absorbed_loss_nonnegative", sql`${table.absorbedLossKobo} >= 0`),
  ],
);
